namespace bgiplayer {
void SoundSubsystem::open_bgm(uint32_t channel, uint32_t state,
                              uint32_t position) {
    auto& slot = bgm_channels_.at(channel);
    slot.opened = true;
    slot.device_state = state;
    slot.position = position;
    slot.control_value = false;
    slot.volume_level = 0x80;
    slot.full_level = 0x80;
    // Original 004C2E00 / 004C35C0 reset both envelope active flags
    // when replacing a stream; secondary channel volume remains configured.
    slot.volume_fade = {};
    slot.full_fade = {};
    slot.silence_fade = {};
}
}  // namespace bgiplayer
